"""Snap span edges to a payroll step and label the result."""

from hourglass.models import Span
from hourglass.parsing import format_span


def check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step!r}")


def snap(minutes: int, step: int) -> int:
    """Nearest multiple of step, halves round up."""
    return (minutes + step // 2) // step * step


def label(span: Span, step: int) -> str:
    start = snap(span.start, step)
    end = snap(span.end, step)
    hours, rest = divmod(end - start, 60)
    text = format_span(Span(start, end))
    return f"{text} ({hours}h {rest}m)"


def round_spans(spans: list[Span], step: int) -> list[str]:
    """Labels like 09:00-17:15 (8h 15m), one per span."""
    check_step(step)
    return [label(span, step) for span in spans]

