# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_spans


class RoundSpansTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 12)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [Span(7 * 60 + 30, 600)]
        self.assertEqual(
            round_spans(spans, 15), ["07:30-10:00 (2h 30m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(180, 240)]
        self.assertEqual(len(round_spans(spans, 30)), 2)

    def test_bad_steps_raise(self):
        spans = [Span(60, 120)]
        for step in (0, -5, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_spans(spans, step)


if __name__ == "__main__":
    unittest.main()
